// NIOGEN | n8n/cadencia/c02_interruptor.js — nó "2 · Interruptor" do mari_cadencia (04/11/2026)
// Kill switch e modo da cadência (staticData). Padrão: DESLIGADA e em modo 'teste'.
//   _cadenciaAtiva  false | true      → false = a rodada para aqui (nada é lido nem enviado)
//   _modoCadencia   'teste' | 'chatwoot'
//       teste    → só conversas canal 'teste' (rota /webhook/mari-teste); envio SIMULADO (grava turno + toque)
//       chatwoot → só conversas canal 'whatsapp'; envio real pela API do Chatwoot (nós 6g/7 hoje desligados)
// Comandos pela rota admin (header X-Mari-Secret): ligar | desligar | modo teste | modo chatwoot | status
// Sem texto de negócio e sem segredo.

const sd = $getWorkflowStaticData('global');
if (sd._cadenciaAtiva === undefined) sd._cadenciaAtiva = false;
if (!sd._modoCadencia) sd._modoCadencia = 'teste';

const ex = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const estado = () => ({ ativa: sd._cadenciaAtiva, modo: sd._modoCadencia, ultima_rodada: sd._ultimaRodada || null });

if (ex('1w · Admin cadência')) {
  const body = $('1w · Admin cadência').first().json.body || {};
  const cmd = String(body.admin || '').toLowerCase().trim();
  if (cmd === 'ligar') sd._cadenciaAtiva = true;
  else if (cmd === 'desligar') sd._cadenciaAtiva = false;
  else if (cmd === 'modo teste' || cmd === 'modo chatwoot') sd._modoCadencia = cmd.split(' ')[1];
  else if (cmd !== 'status') return [{ json: { admin: true, resposta: { erro: 'use: ligar | desligar | modo teste | modo chatwoot | status' } } }];
  return [{ json: { admin: true, resposta: { admin: true, ...estado() } } }];
}

if (!sd._cadenciaAtiva) return [];   // kill switch: nada roda

sd._ultimaRodada = new Date().toISOString();
return [{ json: {
  admin: false,
  modo: sd._modoCadencia,
  canal: sd._modoCadencia === 'chatwoot' ? 'whatsapp' : 'teste',
  agora: sd._ultimaRodada,
  limite: 30,
} }];

// NIOGEN | n8n/cadencia/c03_itens.js — nó "3b · Itens" do mari_cadencia (04/11/2026)
// A RPC mari_cadencia_candidatos devolve um array de objetos (cada um já com a decisão do banco:
// passo, ação, texto, template, params). Aqui só vira um item por conversa — sem decisão nenhuma.
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const lista = Array.isArray(j) ? j : (j && j.conversa_id ? [j] : []);
  for (const c of lista) {
    const v = (c && c.mari_cadencia_candidatos) || c;   // PostgREST pode embrulhar setof jsonb no nome da função
    if (v && v.conversa_id && v.pode_enviar === true) out.push({ json: v });
  }
}
return out.slice(0, 30);   // teto por rodada (o banco já limita; aqui é cinto + suspensório)

// 0142: pedido ao Claude para a Mari escrever a cutucada (só texto; o filtro fica no 4e).

const c = $('4 · Um por vez').first().json;

const ctx = $input.first().json || {};

// 0412 (Ricardo, 25/11: "o mais natural possível e tentar puxar pelo contexto da conversa"): a cutucada parte do que o cliente
// disse e de onde ele parou, não de uma lista de argumentos — na medição de 14 dias, F2–F5 repetiam roteador/2030/rapidinho.
const sistema = `Você é a Mari, vendedora da Nio Internet (fibra) no WhatsApp. O cliente parou de responder e você vai mandar uma
mensagem para retomar a conversa — como uma pessoa do time que lembrou dele, não como lembrete automático.
Como escrever (nesta ordem):
1. Leia as "falas" do contexto. Retome algo CONCRETO que o cliente disse: para quem é a internet, o uso (trabalho, jogo, filho
   estudando, TV), o que incomoda na internet de hoje, a dúvida ou a objeção que ele levantou. Se ele não contou nada pessoal,
   retome o ponto exato onde a conversa parou.
2. Ofereça um caminho para o que travou, em meia frase: sem CEP → pode mandar a rua e o bairro; em dúvida entre planos → ajudar a
   escolher pelo uso que ele contou; achou caro → existe opção mais em conta na tabela (sem citar valor); faltam dados → diga o que falta.
3. Termine com UMA pergunta fácil, de sim/não ou de uma palavra, que puxe o próximo passo do que FALTA.
Regras (todas obrigatórias):
- No máximo 2 frases e 200 caracteres. Português do Brasil, de conversa, sem formalidade. No máximo 1 emoji (pode não ter nenhum).
- Use o primeiro nome do cliente se vier no contexto. Pode citar a cidade e o plano escolhido.
- Argumento de produto só se ele responde ao que o cliente disse, e só do que é verdade: preço fixo até 2030; roteador Wi-Fi
  incluído; a internet mais estável do Brasil (Opensignal). Argumento que já apareceu em qualquer mensagem de "cutucadas_da_conversa"
  NÃO volta. Melhor nenhum argumento do que repetir.
- NUNCA: desconto, brinde, promoção, "última chance", "só hoje", prazo ou data de instalação, valor em R$, "cobertura confirmada",
  asterisco, nome de empresa que não seja Nio, "passando aqui", "só lembrando", "lembrete".
- Não repita nem comece igual a nenhuma mensagem de "cutucadas_ja_enviadas" ou "cutucadas_da_conversa". Não peça desculpa por insistir.
- Se "ja_se_apresentou_mariana" for true: você já se apresentou como Mariana nesta conversa — não se apresente de novo.
- Se "ultima_da_janela" for true: é a última mensagem por enquanto — leve, sem pressão (ex.: deixar o atendimento separado e
  perguntar se quer seguir).
Responda SÓ com o texto da mensagem, sem aspas.`;
// 0412 (Ricardo, 25/11: "Mari vem de Mariana… ela pode se apresentar como Mariana, num tom mais humano. Não estamos mentindo."):
// no passo da chave cadencia_mariana_passo, uma vez por conversa. Sem dizer que é outra pessoa e sem cargo.
const comMariana = ctx.apresentar_como === 'Mariana' ? `

NESTA mensagem você se apresenta pelo seu nome inteiro, Mariana, da Nio — Mari é o apelido. Comece com "Oi, <primeiro nome>! Aqui é
a Mariana, da Nio." (sem o nome do cliente: "Oi! Aqui é a Mariana, da Nio."). O tom é de quem voltou à conversa depois de um tempo
e lembrou do cliente: retome o que ele contou ("fiquei pensando no que você falou de…"). NUNCA diga que é outra pessoa, que
"assumiu" ou "pegou" o atendimento, que é especialista, gerente ou qualquer cargo, nem que é humana; também não diga que é robô.
Nesta mensagem o limite é 240 caracteres.` : '';

// 0314: lembrete que vai com a arte fixa (F3 desde a 0412; era F2) — o texto é a legenda dela e tem de falar do mesmo assunto.

const legenda = String(ctx.imagem_junto || '').trim();

const comImagem = legenda ? `



ESTA cutucada vai como LEGENDA de uma imagem enviada junto. ${legenda}

O texto TEM de conversar com a imagem: o argumento desta vez é a qualidade da internet da Nio (a mais estável do Brasil,

segundo o Opensignal) — pode emendar o preço congelado até 2030. Não descreva a imagem ("veja a imagem") nem invente

prêmio, número ou velocidade que não estão nela. Continue terminando com a pergunta do que FALTA.` : '';

const pedido = {

  model: 'claude-sonnet-5-5', max_tokens: 400,

  output_config: { effort: 'low' },

  system: sistema + comImagem + comMariana,

  messages: [{ role: 'user', content: 'Contexto da conversa (JSON):\n' + JSON.stringify(ctx) }],

};

return [{ json: { pedido } }];

// 0142: filtro da cutucada escrita pela Mari. Reprovou (ou a API falhou) → texto de reserva do banco. Sai o candidato do

// "4 · Um por vez" com o texto final — o 5 · Montar envio segue igual.

const c = { ...$('4 · Um por vez').first().json };

const r = $input.first().json || {};

let ctx = {};

try { ctx = $('4b · Supabase contexto').first().json || {}; } catch (e) { ctx = {}; }

const blocos = Array.isArray(r.content) ? r.content.filter((x) => x && x.type === 'text') : [];

let t = blocos.map((x) => x.text || '').join(' ').replace(/\s+/g, ' ').trim().replace(/^["“']|["”']$/g, '');

const norm = (x) => String(x || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const n = norm(t);

const ja = (Array.isArray(ctx.cutucadas_ja_enviadas) ? ctx.cutucadas_ja_enviadas : []).map(norm);

const ruim = !t || t.length < 12 || t.length > 260 || !t.includes('?') || t.includes('*') || /r\$\s*\d/.test(n)

  || /descont|gratis|gratuit|promo|brinde|ultima chance|so hoje|somente hoje|amanha|instala(cao|r)? (hoje|amanha|em )|prazo|cobertura confirmada|garanto|garantimos|combo|pacote|dh\x61rma|2028/.test(n)

  || ja.some((x) => x && (x === n || x.slice(0, 25) === n.slice(0, 25)))
  // 0412: a Mariana só no passo dela (e sem cargo, sem "outra pessoa"); fora dele, nome nenhum além de Mari
  || (ctx.apresentar_como === 'Mariana') !== /\bmariana\b/.test(n)
  || /especialista|gerente|assumi|peguei seu atendimento|sou humana|sou uma pessoa|passando aqui|so lembrando|lembrete/.test(n)

  || r.stop_reason === 'refusal' || !!r.error;

if (!ruim) c.texto = t;

c.cutucada_ia = !ruim;

return [{ json: c }];

// NIOGEN | n8n/cadencia/c05_montar.js — nó "5 · Montar envio" do mari_cadencia (04/11/2026)
// Recebe UM candidato (loop de 1) e monta o corpo da mensagem para a API do Chatwoot:
//   texto livre (dentro da janela de 24 h) → { content, message_type, private:false }
//   template (fora da janela)              → { content: corpo renderizado, template_params: { name, category,
//                                              language, processed_params: { body: { "1": …, "2": … } } } }
// (formato do noF4b da Renata, capturado do payload da própria UI do Chatwoot).
// semEnvio = true quando NÃO há envio real: modo teste, canal 'teste', telefone de teste 5500000000xxx ou
// passo ENCERRAR (só muda o status). Nunca o nome da revendedora no texto (o banco já filtra; aqui de novo).

const CONFIG = {
  CHATWOOT_NIO_ACCOUNT: '195428',   // conta própria da Nio no Chatwoot (nunca a da Vero) — prompt 28, 07/11
};

const c = $input.first().json;
const modo = $('2 · Interruptor').first().json.modo;
const tel = String(c.telefone || '');
const texto = String(c.texto || '');

const PROIBIDO = new RegExp(['dh' + 'arma', 'gr[aá]tis', 'gratuit', 'combo', 'pacote', 'nio 5g', '2028', 'sem fidelidade'].join('|'), 'i');
let erro = null;
if (c.acao !== 'encerrar' && (!texto || PROIBIDO.test(texto) || texto.includes('*'))) erro = 'texto vazio ou reprovado no filtro de saída';

const semEnvio = c.acao === 'encerrar' || modo !== 'chatwoot' || c.canal === 'teste' || tel.startsWith('5500000000');

let corpo = null;
if (c.acao === 'texto') {
  corpo = { content: texto, message_type: 'outgoing', private: false };
} else if (c.acao === 'template') {
  const body = {};
  (c.params || []).forEach((v, i) => { body[String(i + 1)] = String(v); });
  corpo = {
    content: texto, message_type: 'outgoing', content_type: 'text',
    template_params: { name: c.template, category: c.categoria || 'MARKETING', language: 'pt_BR', processed_params: { body } },
  };
}

if (!semEnvio && !c.chatwoot_conversation_id) erro = erro || 'conversa sem chatwoot_conversation_id';
if (!semEnvio && !CONFIG.CHATWOOT_NIO_ACCOUNT) erro = erro || 'CHATWOOT_NIO_ACCOUNT vazio';

return [{ json: {
  conversaId: c.conversa_id,
  passo: c.proximo_passo,
  acao: c.acao,
  texto,
  excecao: c.excecao || null,
  semEnvio: semEnvio && !erro,
  erro,
  chatwootConversationId: c.chatwoot_conversation_id || null,
  telefone: tel,   // 12/11 (0146): a cutucada com voz/imagem sai pela Graph API
  corpo,
  config: CONFIG,
} }];

// NIOGEN | n8n/cadencia/c06_guard.js — nó "6h · Guard Chatwoot" do mari_cadencia (04/11/2026; porta 21/11/2026)
// 21/11 (fase 2, passo 4 — 0346): antes de QUALQUER envio real, pergunta ao BANCO "pode falar?" (nó 6g, RPC mari_pode_falar com
// p_para 'lembrete' e o passo), que responde pela situação do lead: pessoa ou time na conversa, não contatar, Saída → para a escada
// (mari_cadencia_parar) e não envia; aviso da venda (INSTALACAO, VESPERA, CARTAO…) sai mesmo com o time e nunca para a escada.
// Sem resposta do banco → NÃO envia: vira falha (não queima o passo). Ricardo, 21/11: "Sim, fica calada".
const m = $('5 · Montar envio').first().json;
const r = $input.first().json || {};
const PASSOS_VENDA = ['INSTALACAO', 'VESPERA', 'CARTAO', 'CARTAO2', 'BIO1', 'BIOVOLTA'];
const daVenda = PASSOS_VENDA.includes(String(m.passo || ''));
if (typeof r.pode !== 'boolean') {
  return [{ json: { ...m, parar: false, enviar: false, ok: false, erro: 'banco sem resposta (pode falar?) — não enviado' } }];
}
const naoContatar = !!r.nao_contatar;
const humano = !!r.pessoa;
const time = !!r.time;
const parar = daVenda ? false : !!r.parar;
const resolvida = parar && !humano && !time && !naoContatar;   // "parou pela situação" (Saída, instalada…): o 6p registra como hoje
if (!r.pode && !parar) {
  return [{ json: { ...m, parar: false, enviar: false, ok: false, humano, time, resolvida, naoContatar, daVenda, situacao: r.situacao || null,
    erro: 'não enviado: ' + (r.motivo || 'banco') } }];
}
return [{ json: { ...m, parar, enviar: !!r.pode && !parar, humano, time, resolvida, naoContatar, daVenda, situacao: r.situacao || null,
  motivo: r.motivo || null } }];

// NIOGEN | n8n/cadencia/c06m_midia.js — nó "6m · Mídia?" do mari_cadencia (12/11/2026, 0146)
// docs/Prompt_mari_resposta_audio_121126_1800.md, itens 6 e 6b: a cutucada escolhida vai como IMAGEM do plano (F2, padrão) ou
// como VOZ (F3, padrão), com A/B — metade das conversas recebe a mídia, metade só o texto (bit do id da conversa: voz = bit 0,
// imagem = bit 1; a medição recalcula o grupo pelo mesmo id). Só cutucadas que a Mari escreveu (F1–F5, texto livre na janela de 24 h).
// Config (config_mari_textos): midia_cadencia_ligado ('sim'), midia_cadencia_telefones ('teste' = telefones_teste, '' = todos),
// audio_cadencia_passo, imagem_cadencia_passo, midia_cadencia_ab ('sim'), audio_resposta_voz/modelo/instrucoes.
// Qualquer dúvida → sem mídia (a cutucada segue em texto pelo Chatwoot, como sempre).
const m = $('6h · Guard Chatwoot').first().json;
const ex = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const sem = (motivo) => [{ json: { ...m, midia: null, midiaMotivo: motivo } }];
if (m.acao !== 'texto' || !/^F[1-5]$/.test(String(m.passo || ''))) return sem('não é cutucada escrita');
const cfg = ((ex('6k · Supabase config') ? $('6k · Supabase config').first().json : null) || {}).textos || {};
if (String(cfg.midia_cadencia_ligado || '').toLowerCase() !== 'sim') return sem('desligado');
const tel = String(m.telefone || '').replace(/\D/g, '');
const lista = String(cfg.midia_cadencia_telefones == null ? 'teste' : cfg.midia_cadencia_telefones).trim();
const liberados = (lista === 'teste' ? String(cfg.telefones_teste || '') : lista).split(/[^0-9]+/).filter(Boolean);
if (lista !== '' && !liberados.includes(tel)) return sem('telefone fora da lista');
const tipo = m.passo === String(cfg.audio_cadencia_passo || '') ? 'voz' : m.passo === String(cfg.imagem_cadencia_passo || '') ? 'imagem' : null;
if (!tipo) return sem('passo sem mídia');
// A/B pelo id da conversa (estável): bit 0 → voz, bit 1 → imagem. 0 = grupo da mídia.
const byte = parseInt(String(m.conversaId || '').replace(/-/g, '').slice(-2), 16) || 0;
const ab = String(cfg.midia_cadencia_ab || 'sim').toLowerCase() === 'sim';
const grupoMidia = !ab || (tipo === 'voz' ? (byte & 1) === 0 : ((byte >> 1) & 1) === 0);
if (!grupoMidia) return sem(`A/B: grupo texto (${tipo})`);
const texto = String(m.texto || '').trim();
const base = { tipo, telefone: tel, texto, origem: 'cadencia', passo: m.passo, ab: tipo === 'voz' ? 'voz' : 'imagem',
  conversa_id: m.conversaId, chatwoot_conversa: m.chatwootConversationId || null };
if (tipo === 'voz') {
  // voz: curta e sem nada que precise ser lido (preço, número, link)
  if (texto.length > 250 || /R\$|\d{4,}|https?:\/\//.test(texto)) return sem('texto não cabe em voz');
  return [{ json: { ...m, midia: 'voz', pedidoMidia: { ...base, texto: texto.replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, '').replace(/\s+/g, ' ').trim(),
    voz: cfg.audio_resposta_voz || 'marin', modelo: cfg.audio_resposta_modelo || 'gpt-4o-mini-tts', instrucoes: cfg.audio_resposta_instrucoes || '' } } }];
}
// imagem: o cartão do plano que o 4b trouxe para ESTA conversa e ESTE passo
const ctx = ex('4b · Supabase contexto') ? ($('4b · Supabase contexto').first().json || {}) : {};
const md = ctx.midia || {};
if (ctx.conversa_id !== m.conversaId || ctx.passo !== m.passo || !/^https:\/\//.test(String(md.imagem_url || ''))) return sem('sem imagem do plano');
return [{ json: { ...m, midia: 'imagem', pedidoMidia: { ...base, imagem_url: md.imagem_url, plano: md.plano_da_imagem || null } } }];

// NIOGEN | n8n/cadencia/c06q_resultado_midia.js — nó "6q · Resultado mídia" do mari_cadencia (12/11/2026, 0146)
// A mídia saiu → item no formato que o 7r espera (id + status), a cutucada conta como enviada. Não saiu → volta o item da cutucada
// para o "7 · Chatwoot enviar" (texto, como sempre). O erro já foi gravado pelo mari_midia_envio.
const m = $('6m · Mídia?').first().json;
const r = $input.first().json || {};
if (r.ok) return [{ json: { id: r.wamid || 'whatsapp', status: 'sent', midiaOk: true } }];
const { pedidoMidia, ...resto } = m;
return [{ json: { ...resto, midiaOk: false } }];

// NIOGEN | n8n/cadencia/c07_resultado.js — nó "7r · Resultado" do mari_cadencia (04/11/2026)
// Lê a resposta do POST no Chatwoot: ok só com id da mensagem e status ≠ 'failed' (a Meta recusou).
// Nó 7 desligado → chega o próprio item montado (sem id) → falha registrada, passo não queima.
const g = $('6h · Guard Chatwoot').first().json;
const r = $input.first().json || {};
const ok = !!r.id && r.status !== 'failed' && !r.conversaId;
return [{ json: { ...g, ok, erro: ok ? null : (r.error || r.message || `chatwoot sem id (status=${r.status || 'nenhum'})`) } }];

// NIOGEN | n8n/cadencia/c09b_futuro_itens.js — nó "9b · Itens futuro" do mari_cadencia (07/11/2026, prompt 28)
// A RPC mari_futuro_pendentes (0052) devolve as conversas cuja venda está em Saída "Interesse futuro (com data)" e
// ainda sem a etiqueta/nota para essa data. Aqui só vira um item por conversa — sem decisão nenhuma.
// RPC com erro (ex.: 0052 ainda não aplicada) → nada a fazer nesta rodada (o ramo principal não é afetado).
const CHATWOOT_NIO_ACCOUNT = '195428';   // conta própria da Nio no Chatwoot (nunca a da Vero) — a mesma do c05
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j || j.error || j.code || (j.message && !j.conversa_id)) continue;   // erro da RPC: pula
  const lista = Array.isArray(j) ? j : (j.conversa_id || j.mari_futuro_pendentes ? [j] : []);
  for (const x of lista) {
    const v = (x && x.mari_futuro_pendentes) || x;
    if (v && v.conversa_id && v.chatwoot_conversation_id && v.volta_em) {
      out.push({ json: { conta: CHATWOOT_NIO_ACCOUNT, conversaId: v.conversa_id, cw: String(v.chatwoot_conversation_id),
        voltaEm: v.volta_em, nota: v.nota } });
    }
  }
}
return out.slice(0, 20);

// NIOGEN | n8n/cadencia/c09h_futuro_conferir.js — nó "9h · Conferir" do mari_cadencia (07/11/2026; porta 21/11/2026)
// 21/11 (fase 2, passo 4 — 0346): a etiqueta interesse-futuro e a nota não vão mais direto ao Chatwoot: o nó 9f pede ao banco
// (RPC mari_chatwoot_pedir, pedido 'interesse_futuro'), que põe as duas ordens na fila pela porta (etiqueta por add, nunca a
// lista inteira). Marca a conversa (mari_futuro_marcar) só quando o banco aceitou; senão a próxima rodada tenta de novo.
const out = [];
$input.all().forEach((it, i) => {
  const base = $('9b · Itens futuro').itemMatching(i).json;
  const r = it.json || {};
  const ok = r.ok === true;
  out.push({ json: { ...base, marcar: ok, erro: ok ? null : 'porta: ' + (r.erro || 'sem resposta do banco') } });
});
return out;
